-- Rivers and Lakes Tea: Zhengyan Series rock oolongs (from zhengyan-true-cliff-rock-oolong page)
-- 10 teas, extracted as individual teas from the series page (sold as 7g session packets).
-- Producers: Shengfa (DSK), Asong (HYK), Shiqi "17" (Zhuke/Shijiao etc). All rested 1-2 yrs post roast.
-- Locale/cultivar names verified: Miaolian 妙莲 (Lotus Peak area), Da Keng Kou 大坑口, Hui Yuan Keng 慧苑坑,
-- Guanyin Yan 观音岩, Dao Shui Keng 倒水坑, Zhuke 竹窠 + Aijiao Wulong 矮脚乌龙 (Beiyuan heritage cv),
-- Shijiao 石角, Ma Tou Yan 马头岩, Beidou 北斗 (true DHP cv).
INSERT INTO teas (name, slug, phonetic_name, original_name, description, origin, tea_type, category, caffeine_level, brewing_temp_c, brewing_time_min, brewing_num_brews, brewing_instructions, characteristics, health_benefits, color_hex, oxidation_level, roast_level, flavor_x, flavor_y, source_type, source, owner_id, is_public) VALUES
  ('Miaolian Shui Xian', 'miaolian-shui-xian', 'Miàolián Shuǐxiān', '妙莲水仙', 'The core tea production arena in the Wuyi Mountains referred to as 正岩 zheng yan "true cliff" is regarded as the highest pedigree of terroir when it comes to Rock Oolong: jagged, idyllic cliffs harbor tea gardens between them, feeding the soil a consistent runoff of minerals experienced in the finished tea as 岩韵 yan yun "rock charm". All ten teas rested 1–2 years after their last roasting, allowing the necessary 退火 "retreating fire".

Over the last seven years of traveling to, developing relationships in, and continually learning about and tasting rock oolong, Rivers and Lakes curated a lineup of high quality, genuine, true cliff Wuyi teas — sold here as 7g session packets. Producers: Shengfa, a third generation tea maker whose Dao Shui Keng Rougui is among the smoothest; Asong, married into one of the 13 original Hui Yuan Keng families who own (and don''t contract out) around 50亩 (over 8 acres) there; and Shiqi "17", a well-connected tea project leader contracting fresh leaves from sought micro terroirs around Shui Lian Dong and Hui Yuan Keng — many of his teas are lao cong, heavier roasted, often semi-wild seed grown, from unpruned gardens.

Zhengyan ("true cliff") Shui Xian rock oolong from the Miaolian grove in the Wuyi Mountain core, roasted medium and rested.', 'Miaolian, Wuyishan, Nanping, Fujian, China', 'oolong', 'true_tea', 'medium', 95, 1, 6, 'Use 5g per 150ml at 95–100°C. Quick rinse; steep 20–40 seconds; re-steep 5–7 times.', ARRAY['Mineral', 'Floral', 'Roasted', 'Smooth']::text[], ARRAY[]::text[], '#D4852A', 45, 50, 58, 32, 'default', 'Teapp', NULL, TRUE),
